typedef struct {
    int h, r;
} Doll;

int cmp(const void *a, const void *b) {
    Doll *da = (Doll*)a;
    Doll *db = (Doll*)b;
    if (da->h != db->h) return da->h - db->h;
    return db->r - da->r; // descending r for same h
}

int maxNested(Doll *dolls, int n) {
    // Sort by height ascending, for same height by radius descending
    qsort(dolls, n, sizeof(Doll), cmp);

    // LIS on radius (strictly increasing)
    int *dp = malloc(n * sizeof(int));
    int len = 0;
    for (int i = 0; i < n; i++) {
        int lo = 0, hi = len;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (dp[mid] < dolls[i].r) lo = mid + 1;
            else hi = mid;
        }
        dp[lo] = dolls[i].r;
        if (lo == len) len++;
    }
    free(dp);
    return len;
}

