#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int h, r;
} Doll;

static int cmp_doll(const void *a, const void *b) {
    const Doll *x = (const Doll *)a;
    const Doll *y = (const Doll *)b;
    if (x->h != y->h) return x->h - y->h;
    return x->r - y->r;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n != 0) {
        Doll *A = (Doll *)malloc(sizeof(Doll) * n);
        Doll *B = (Doll *)malloc(sizeof(Doll) * n);
        if (!A || !B) return 0;

        for (int i = 0; i < n; i++) scanf("%d %d", &A[i].h, &A[i].r);
        for (int i = 0; i < n; i++) scanf("%d %d", &B[i].h, &B[i].r);

        qsort(A, n, sizeof(Doll), cmp_doll);
        qsort(B, n, sizeof(Doll), cmp_doll);

        int ans = 0;
        int j = 0;
        for (int i = 0; i < n; i++) {
            while (j < n) {
                if (B[j].h < A[i].h && B[j].r < A[i].r) {
                    ans++;
                    j++;
                    break;
                }
                j++;
            }
            if (j >= n) break;
        }

        printf("%d\n", ans);

        free(A);
        free(B);
    }
    return 0;
}

