import sys

def lis_strict_2d(items):
    # items: list of (h, r)
    # Sort by h asc, and for equal h by r desc.
    # Then answer is LIS length on r with strict increasing.
    items.sort(key=lambda x: (x[0], -x[1]))
    tails = []
    for _, r in items:
        # lower_bound for r in tails
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < r:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(r)
        else:
            tails[lo] = r
    return len(tails)

