import java.io.*;
import java.util.*;

public class Main {
    static class Doll implements Comparable<Doll> {
        int h, r;
        Doll(int h, int r) {
            this.h = h;
            this.r = r;
        }
        public int compareTo(Doll other) {
            if (this.h != other.h) return Integer.compare(this.h, other.h);
            return Integer.compare(this.r, other.r);
        }
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        while ((line = br.readLine()) != null) {
            int n = Integer.parseInt(line.trim());
            if (n == 0) break;
            Doll[] ichiro = new Doll[n];
            for (int i = 0; i < n; i++) {
                String[] parts = br.readLine().split(" ");
                int h = Integer.parseInt(parts[0]);
                int r = Integer.parseInt(parts[1]);
                ichiro[i] = new Doll(h, r);
            }
            int m = Integer.parseInt(br.readLine().trim());
            Doll[] jiro = new Doll[m];
            for (int i = 0; i < m; i++) {
                String[] parts = br.readLine().split(" ");
                int h = Integer.parseInt(parts[0]);
                int r = Integer.parseInt(parts[1]);
                jiro[i] = new Doll(h, r);
            }

            // Combine both sets
            List<Doll> all = new ArrayList<>();
            for (Doll d : ichiro) all.add(d);
            for (Doll d : jiro) all.add(d);
            Collections.sort(all);

            // LIS on radius with strict increasing constraints
            // Since heights are sorted ascending, we need strictly increasing radius
            // for strictly increasing height (height ties cannot contain each other)
            // Process in order, and for equal heights, we must avoid using same height dolls
            // in increasing radius order because they cannot contain each other.
            // Solution: when heights equal, process radii in descending order for LIS
            // to avoid using two dolls with same height in same increasing sequence.

            // We'll do coordinate compression on radius for BIT/LIS
            // First collect all radii
            TreeSet<Integer> radiiSet = new TreeSet<>();
            for (Doll d : all) radiiSet.add(d.r);
            Map<Integer, Integer> comp = new HashMap<>();
            int idx = 1;
            for (int r : radiiSet) comp.put(r, idx++);

            // Fenwick tree for maximum length ending with radius <= x
            int size = comp.size();
            int[] bit = new int[size + 2];

            // Group by height
            Map<Integer, List<Integer>> heightToRadii = new TreeMap<>();
            for (Doll d : all) {
                heightToRadii.computeIfAbsent(d.h, k -> new ArrayList<>()).add(comp.get(d.r));
            }

            for (int h : heightToRadii.keySet()) {
                List<Integer> radii = heightToRadii.get(h);
                // Process in descending order of radius to avoid same height interference
                Collections.sort(radii, Collections.reverseOrder());
                // For each radius, we need to compute best before updating BIT
                // But to avoid using same height, we store updates temporarily
                List<int[]> updates = new ArrayList<>();
                for (int rComp : radii) {
                    int best = query(bit, rComp - 1) + 1;
                    updates.add(new int[]{rComp, best});
                }
                for (int[] upd : updates) {
                    update(bit, upd[0], upd[1]);
                }
            }

            int result = query(bit, size);
            System.out.println(result);
        }
    }

    static int query(int[] bit, int idx) {
        int res = 0;
        while (idx > 0) {
            res = Math.max(res, bit[idx]);
            idx -= idx & -idx;
        }
        return res;
    }

    static void update(int[] bit, int idx, int val) {
        while (idx < bit.length) {
            bit[idx] = Math.max(bit[idx], val);
            idx += idx & -idx;
        }
    }
}

