public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            int[][] dolls = new int[n][2];
            for (int i = 0; i < n; i++) {
                dolls[i][0] = sc.nextInt();
                dolls[i][1] = sc.nextInt();
            }
            // Sort by height desc, then radius desc
            Arrays.sort(dolls, (a, b) -> a[0] != b[0] ? b[0] - a[0] : b[1] - a[1]);
            // Find longest strictly decreasing subsequence in radius
            // = longest strictly increasing subsequence in negated radius
            // tails[i] = smallest ending value of increasing subseq of length i+1
            ArrayList<Integer> tails = new ArrayList<>();
            for (int[] d : dolls) {
                int r = -d[1]; // negate for increasing
                int pos = lowerBound(tails, r);
                if (pos == tails.size()) tails.add(r);
                else tails.set(pos, r);
            }
            System.out.println(tails.size());
        }
    }

    static int lowerBound(ArrayList<Integer> list, int val) {
        int lo = 0, hi = list.size();
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (list.get(mid) < val) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Doll {
        int h, r, owner; // owner: 0 = Ichiro, 1 = Jiro
        Doll(int h, int r, int owner) {
            this.h = h;
            this.r = r;
            this.owner = owner;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            int n = fs.nextInt();
            if (n == 0) break;

            Doll[] dolls = new Doll[2 * n];
            for (int i = 0; i < n; i++) {
                int h = fs.nextInt();
                int r = fs.nextInt();
                dolls[i] = new Doll(h, r, 0);
            }
            for (int i = 0; i < n; i++) {
                int h = fs.nextInt();
                int r = fs.nextInt();
                dolls[n + i] = new Doll(h, r, 1);
            }

            Arrays.sort(dolls, (a, b) -> {
                if (a.h != b.h) return a.h - b.h;
                return a.r - b.r;
            });

            int[] dp0 = new int[2 * n]; // best chain ending at i with owner 0
            int[] dp1 = new int[2 * n]; // best chain ending at i with owner 1
            int ans = 0;

            for (int i = 0; i < 2 * n; i++) {
                if (dolls[i].owner == 0) dp0[i] = 1;
                else dp1[i] = 1;

                for (int j = 0; j < i; j++) {
                    if (dolls[j].h < dolls[i].h && dolls[j].r < dolls[i].r) {
                        if (dolls[i].owner == 0) {
                            dp0[i] = Math.max(dp0[i], dp1[j] + 1);
                        } else {
                            dp1[i] = Math.max(dp1[i], dp0[j] + 1);
                        }
                    }
                }

                ans = Math.max(ans, Math.max(dp0[i], dp1[i]));
            }

            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}
